+package spoonbill.internal;
+
+import java.util.concurrent.atomic.AtomicIntegerFieldUpdater;
+
+/** Atomic storage for a lane item's completion, accessed only within the lane package. */
+abstract class SerialLaneHandoff {
+    private static final AtomicIntegerFieldUpdater<SerialLaneHandoff> PHASE =
+        AtomicIntegerFieldUpdater.newUpdater(SerialLaneHandoff.class, "phase");
+
+    private volatile int phase;
+
+    SerialLaneHandoff(int initialPhase) {
+        PHASE.set(this, initialPhase);
+    }
+
+    final int swapPhase(int next) {
+        return PHASE.getAndSet(this, next);
+    }
+
+    final void setPhase(int next) {
+        PHASE.set(this, next);
+    }
+}

