package spoonbill.internal.backendperf

import java.nio.file.Path
import java.util.concurrent.{CountDownLatch, Executors, Semaphore, TimeUnit}
import java.util.concurrent.atomic.AtomicReference
import scala.concurrent.{Await, ExecutionContext}
import scala.concurrent.duration.*
import spoonbill.Extension
import spoonbill.effect.{Effect, Reporter}
import spoonbill.internal.ExtensionRuntime

/** Single-view callback qualification. Each backend runs the same fixture in each arm. */
object NativeBackendDelivery {
  private final case class Value(writer: Int, sequence: Int, sent: Long)

  private final class Reports extends Reporter {
    val first = new AtomicReference[Throwable]()
    def error(message: String, cause: Throwable): Unit = { first.compareAndSet(null, new IllegalStateException(message, cause)); () }
    def error(message: String): Unit = error(message, null)
    def warning(message: String, cause: Throwable): Unit = error(message, cause)
    def warning(message: String): Unit = error(message)
    def info(message: String): Unit = ()
    def debug(message: String): Unit = ()
    def debug(message: String, a: Any): Unit = ()
    def debug(message: String, a: Any, b: Any): Unit = ()
    def debug(message: String, a: Any, b: Any, c: Any): Unit = ()
    def check(): Unit = Option(first.get()).foreach(error => throw error)
  }

  // Same microsecond bucket boundaries and p99 rank as ExtensionRuntimeBenchmark.
  private final class Histogram {
    val buckets = new Array[Long](100001)
    var count = 0L
    def add(ns: Long): Unit = {
      val us = ns / 1000L
      val bin = if (us < 10000L) us else 10000L + (us - 10000L) / 100L
      buckets(math.min(bin, buckets.length.toLong - 1).toInt) += 1
      count += 1
    }
    def p99Ms: Double = {
      require(count > 0L && buckets.last == 0L, "Invalid or overflowing histogram")
      val rank = math.ceil(count * 0.99).toLong
      var i = 0
      var sum = 0L
      while (sum < rank) { sum += buckets(i); i += 1 }
      val bin = i - 1
      (if (bin <= 10000) bin.toLong else 10000L + (bin - 10000L) * 100L) / 1000.0
    }
  }

  private def verifyOrigins(adapter: String): Unit = {
    def source(name: String): Path =
      Path.of(Class.forName(name).getProtectionDomain.getCodeSource.getLocation.toURI).toRealPath()
    val frozen = Path.of(sys.props("bench.frozenRoot")).toRealPath()
    val overlay = Path.of(sys.props("bench.overlayRoot")).toRealPath()
    for (name <- List("spoonbill.internal.ExtensionRuntime", "spoonbill.internal.ExtensionMachine$",
                      "spoonbill.internal.SerialLane", "spoonbill.effect.Effect"))
      require(source(name).startsWith(frozen), s"Wrong source for $name")
    require(source(adapter) == overlay.resolve("adapter"), "Wrong adapter source")
    require(source(getClass.getName) == overlay.resolve("fixture"), "Wrong fixture source")
  }

  def run[F[_]](backend: String, adapter: String, args: Array[String])(using effect: Effect[F]): Unit = {
    val Array(label, warmArg, secondsArg) = args
    require(label.matches("[a-zA-Z0-9_-]+"))
    val warm = warmArg.toInt
    val seconds = secondsArg.toInt
    require(warm > 0 && seconds > 0)
    verifyOrigins(adapter)
    val writers = 4
    val extensions = 3
    val window = 1024
    val pool = Executors.newFixedThreadPool(4)
    given ExecutionContext = ExecutionContext.fromExecutorService(pool)
    val bound = new ExtensionRuntime.Bound[F] {
      def apply[A](operation: => F[A], late: A => F[Unit]): F[A] = operation
    }
    def await[A](op: F[A]): A = Await.result(effect.toFuture(op), 30.seconds)

    def round(duration: Int, measured: Boolean): Unit = {
      val ready = new CountDownLatch(1)
      val permits = new Semaphore(window)
      val reports = new Reports
      val initial = Value(-1, 0, 0L)
      val delivered = new Histogram
      val counts = new Array[Long](extensions)
      val previous = Array.ofDim[Int](extensions, writers)
      val latest = Array.fill(extensions)(initial)
      var chosen: Value = initial
      var nextSlot = 0
      var nextDestroy = extensions - 1
      val observers = List.tabulate(extensions) { slot =>
        Extension[F, Value, Unit](s"observer-$slot") { _ =>
          effect.pure(Extension.Handlers[F, Value, Unit](
            onState = value => effect.delay {
              if (slot == 0) chosen = value
              if (slot != nextSlot || !(chosen eq value)) reports.error("Callbacks out of extension order")
              nextSlot = (slot + 1) % extensions
              latest(slot) = value
              if (value.writer < 0) {
                if (slot == extensions - 1) ready.countDown()
              } else {
                if (value.sequence != previous(slot)(value.writer) + 1) reports.error("Missing, duplicate or reordered state")
                previous(slot)(value.writer) = value.sequence
                counts(slot) += 1
                if (slot == extensions - 1) {
                  delivered.add(System.nanoTime() - value.sent)
                  permits.release()
                }
              }
            },
            onDestroy = value => effect.delay {
              if (slot != nextDestroy || !(value eq latest(slot))) reports.error("Incorrect teardown order or last state")
              nextDestroy -= 1
            }
          ))
        }
      }
      val runtime = new ExtensionRuntime[F, Value, Unit](observers, reports, bound, None)
      await(runtime.setup(null, initial, () => effect.unit))
      await(runtime.start())
      require(ready.await(30, TimeUnit.SECONDS), "Attach did not complete")
      val armed = new CountDownLatch(writers)
      val start = new CountDownLatch(1)
      val finished = new CountDownLatch(writers)
      val offered = new Array[Long](writers)
      @volatile var deadline = 0L
      val producers = Vector.tabulate(writers) { writer => new Thread(() => {
        try {
          armed.countDown()
          require(start.await(30, TimeUnit.SECONDS), "Start gate stalled")
          var sequence = 0
          while (System.nanoTime() < deadline) {
            require(permits.tryAcquire(30, TimeUnit.SECONDS), "Delivery stalled")
            if (System.nanoTime() < deadline) {
              sequence += 1
              runtime.state(Value(writer, sequence, System.nanoTime()))
            } else permits.release()
          }
          offered(writer) = sequence
        } catch { case error: Throwable => reports.error("Producer failed", error) }
        finally finished.countDown()
      }, s"backend-writer-$writer") }
      producers.foreach(_.start())
      val elapsed = try {
        require(armed.await(30, TimeUnit.SECONDS), "Writers not ready")
        val before = System.nanoTime()
        deadline = before + duration.seconds.toNanos
        start.countDown()
        require(finished.await(duration.toLong + 35L, TimeUnit.SECONDS), "Writers stalled")
        reports.check()
        require(permits.tryAcquire(window, 30, TimeUnit.SECONDS), "Backlog did not drain")
        System.nanoTime() - before
      } finally {
        start.countDown()
        producers.foreach(_.join())
      }
      val sent = offered.sum
      require(sent > 0 && counts.forall(_ == sent) && delivered.count == sent && nextSlot == 0)
      require(previous.forall(row => row.indices.forall(i => row(i).toLong == offered(i))), "A producer's suffix was lost")
      val p99 = delivered.p99Ms
      await(runtime.destroy())
      reports.check()
      require(runtime.pending == 0 && nextDestroy == -1, "Incomplete teardown")
      if (measured) {
        val wall = elapsed / 1e9
        println(s"""{"backend":"$backend","label":"$label","writers":4,"views":1,"extensions":3,"window":1024,"warmupSeconds":$warm,"seconds":$duration,"completed":$sent,"callbacks":${counts.sum},"elapsedSeconds":$wall,"notificationsPerSecond":${sent/wall},"deliveryP99Ms":$p99,"correct":true}""")
      }
    }
    try { round(warm, false); round(seconds, true) }
    finally { pool.shutdownNow(); pool.awaitTermination(5, TimeUnit.SECONDS) }
  }
}

